import { graphql, useStaticQuery } from 'gatsby';
import { TheAppContext } from 'provider/AppContext';
import { useContext, useMemo } from 'react';

export type SkillItem = {
  id: string;
  attributes: {
    date_started: string;
    slug: string;
    SkillCategory: 'frontend' | 'backend' | 'other' | 'creative' | 'ai_ml';
    skill: {
      id: number;
      Link: string;
      Mastery: 'To Do' | 'In Progress' | 'Mastered';
      SkillName: string;
      Icon: {
        data: {
          attributes: {
            url: string;
          };
        };
      };
    };
  };
};

export const useAllSkills = () => {
  const { skillSortAsc } = useContext(TheAppContext);
  const data: { strapi: { skills: { data: SkillItem[] } } } = useStaticQuery(
    graphql`
      query AllSkills {
        strapi {
          skills(pagination: { limit: 100 }) {
            data {
              id
              attributes {
                date_started
                SkillCategory
                slug
                skill {
                  id
                  Link
                  Mastery
                  SkillName
                  Icon {
                    data {
                      attributes {
                        url
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    `,
  );

  const earliestDate = useMemo(
    () =>
      new Date(
        data.strapi.skills.data.sort((a, b) => {
          const d1 = Date.parse(a.attributes.date_started);
          const d2 = Date.parse(b.attributes.date_started);
          return d2 - d1;
        })[data.strapi.skills.data.length - 1]?.attributes
          .date_started as unknown as any,
      ),
    [],
  );
  return {
    skills: data.strapi.skills.data.sort((a, b) => {
      const d1 = Date.parse(a.attributes.date_started);
      const d2 = Date.parse(b.attributes.date_started);
      return skillSortAsc === 'asc' ? d1 - d2 : d2 - d1;
    }),
    earliestDate,
    latestDate: new Date(),
    timeRange:
      Date.parse(new Date().toString()) -
      Date.parse(earliestDate.toDateString()),
  };
};
