import styled from '@emotion/styled';
import { Box, Chip, Typography } from '@mui/material';
import { Stack } from '@mui/system';
import { graphql, Link, useStaticQuery } from 'gatsby';
import { GatsbyImage, getImage } from 'gatsby-plugin-image';
import Layout from '../layouts';
import React, { useContext, useEffect, useRef, useState } from 'react';
import HalfHero from '../components/AboutPage/HalfHero';
import AllItems from '../components/AllItems';
import MegaMenu from '../components/Codes/MegaMenu';
import SplashMenu from '../components/HamburgerMenu/SplashMenu';
import Navbar from '../components/Shared/Navbar';
import { rotate } from '../components/Splash';
import { ASLogo } from '../components/Splash/ASLogo';
import { TheAppContext } from '../provider/AppContext';
import { useDetectSticky } from '../hooks/useDetectIsSticky';
const Styled__Wrap = styled(Box)`
  background-color: #f7f7f7;
  padding: 2rem;
  padding-top: 0;
`;

const Styled__FilterSection = styled(Box)`
  background-color: white;
  position: sticky;
  top: 55px;
  margin-bottom: 1rem;
  display: flex;
  margin-left: -2rem;
  margin-right: -2rem;
  padding: 1.25rem 4rem;
  align-items: center;
  justify-content: space-between;
  &.sticky {
    background-color: rgba(255, 255, 255, 0.524);
    backdrop-filter: blur(10px);
  }
`;
const Everything = () => {
  const { menuOpen } = useContext(TheAppContext);
  const [isSticky, setIsSticky] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  // const [isSticky, ref] = useDetectSticky();
  // console.log('isSticky', isSticky);
  const data = useStaticQuery(graphql`
    {
      e: strapiEverything {
        HeaderImage {
          localFile {
            childImageSharp {
              gatsbyImageData(
                transformOptions: {
                  duotone: { shadow: "#1c1c1c", highlight: "#814bff" }
                }
              )
            }
          }
        }
      }
    }
  `);

  const [hidden, setHidden] = useState(false);

  useEffect(() => {
    setHidden(!menuOpen);
  }, [menuOpen]);

  useEffect(() => {
    document.addEventListener('scroll', () => {
      if (ref.current?.offsetTop !== 392) {
        setIsSticky(true);
      }
    });
    return () => {
      document.removeEventListener('scroll', () => {});
    };
  }, []);
  return (
    <Layout>
      <MegaMenu />
      <Navbar />
      <Box sx={{ position: 'relative', height: '40vh', overflow: 'hidden' }}>
        <GatsbyImage
          alt=""
          image={getImage(data.e.HeaderImage.localFile)!}
          style={{
            position: 'fixed',
            zIndex: -1,
            objectPosition: 'center 100%',
            transform: `translate(0%, -30%)`,
            objectFit: 'contain',
          }}
        />
        <Box
          sx={{
            p: 5,
            height: '100%',
            display: 'flex',
            justifyContent: 'flex-end',
            flexDirection: 'column',
          }}
        >
          <Typography variant="h3" sx={{ color: 'white', textAlign: 'center' }}>
            Everything
          </Typography>
        </Box>
      </Box>

      <Styled__Wrap>
        <Styled__FilterSection ref={ref} className={isSticky ? 'sticky' : ''}>
          <Box sx={{ justifySelf: 'flex-start' }}>
            <Typography variant="h5" color={'primary.text'}>
              Filter
            </Typography>
          </Box>
          <Stack
            direction={'row'}
            justifyContent="center"
            gap="1rem"
            flexWrap={'wrap'}
          >
            <Chip
              label="Codes"
              variant="filled"
              color="secondary"
              sx={{ fontWeight: 600 }}
            />
            <Chip
              label="Words"
              variant="filled"
              color="warning"
              sx={{ fontWeight: 600 }}
            />
            <Chip
              label="Pixels"
              variant="filled"
              sx={{ fontWeight: 600 }}
              color="primary"
            />
            <Chip
              label="Sounds"
              variant="filled"
              color="error"
              sx={{ fontWeight: 600 }}
            />
          </Stack>
        </Styled__FilterSection>

        <Box sx={{ pt: 1, maxWidth: 'calc(1050px + 4rem)', margin: 'auto' }}>
          <AllItems />
        </Box>
      </Styled__Wrap>
    </Layout>
  );
};

// export const query = graphql`
