import React from 'react';
import { Item__Props } from './ItemMap';
import SingleItem from './SingleItem';
import { GatsbyImage } from 'gatsby-plugin-image';
import { useAllSkills } from '../../hooks/useAllSkills';
const ProjectItem = (props: Item__Props) => {
  const { skills: allSkills } = useAllSkills();
  return (
    <SingleItem
      skills={allSkills.filter((s) =>
        props.skillIds.includes(Number(s.attributes.skill.id))
      )}
      thumbnailComponent={
        <img
          alt="project"
          style={{ maxWidth: '350px', height: 'auto' }}
          src={
            props?.image?.url ||
            'https://generative-placeholders.glitch.me/image?width=350&height=300&style=mondrian&colors=0'
          }
        />
      }
      {...props}
    />
  );
};

export default ProjectItem;
