import { graphql, useStaticQuery } from 'gatsby';
import { MusicType } from '../components/AllItems/ItemMap';

export type MusicItem = {
  id: string;
  attributes: {
    Title: string;
    artist: string;
    embedLink: string;
    released: string;
    platform: MusicType;
    link: string;
    tags: {
      data: {
        attributes: { tagName: string };
      }[];
    };
    Narrative: string;
    artwork: {
      data: {
        id: string;
        attributes: {
          url: string;
          alternativeText: string;
        };
      }[];
    };
  };
};

export const useAllMusic = () => {
  const data: { strapi: { musics: { data: MusicItem[] } } } =
    useStaticQuery(graphql`
      query AllMusic {
        strapi {
          musics {
            data {
              attributes {
                Title
                platform
                artist
                released
                embedLink
                link
                tags {
                  data {
                    attributes {
                      tagName
                    }
                  }
                }
                Narrative
                artwork {
                  data {
                    attributes {
                      alternativeText
                      url
                    }
                    id
                  }
                }
              }
              id
            }
          }
        }
      }
    `);
  return data.strapi.musics.data;
};
